const orders  = $('Read Orders').all().map(i => i.json);
const feedback = $('Read Feedback').all().map(i => i.json);
const tickets  = $('Read Support Tickets').all().map(i => i.json);

// Get date range — last 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

function isWithinLastWeek(dateStr) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  return d >= sevenDaysAgo && d <= now;
}

// Filter to last 7 days
const recentOrders = orders.filter(o => isWithinLastWeek(o.order_date));
const recentFeedback = feedback.filter(f => isWithinLastWeek(f.feedback_date));
const recentTickets = tickets.filter(t => isWithinLastWeek(t.ticket_date));

// ── ORDERS ANALYSIS ──────────────────────────────────────

const totalOrders = recentOrders.length;

const totalRevenue = recentOrders
  .filter(o => o.order_status === 'Delivered')
  .reduce((sum, o) => sum + (parseFloat(o.total_amount) || 0), 0);

const avgOrderValue = totalOrders > 0 
  ? (totalRevenue / totalOrders).toFixed(2) 
  : 0;

// Count by status
const statusCounts = recentOrders.reduce((acc, o) => {
  acc[o.order_status] = (acc[o.order_status] || 0) + 1;
  return acc;
}, {});

// Revenue by category
const categoryRevenue = recentOrders
  .filter(o => o.order_status === 'Delivered')
  .reduce((acc, o) => {
    acc[o.category] = (acc[o.category] || 0) + (parseFloat(o.total_amount) || 0);
    return acc;
  }, {});

const topCategory = Object.entries(categoryRevenue)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

// Revenue by city
const cityRevenue = recentOrders
  .filter(o => o.order_status === 'Delivered')
  .reduce((acc, o) => {
    acc[o.city] = (acc[o.city] || 0) + (parseFloat(o.total_amount) || 0);
    return acc;
  }, {});

const topCity = Object.entries(cityRevenue)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

// Payment method breakdown
const paymentCounts = recentOrders.reduce((acc, o) => {
  acc[o.payment_method] = (acc[o.payment_method] || 0) + 1;
  return acc;
}, {});

// Cancellation and return rates
const cancelRate = totalOrders > 0 
  ? ((statusCounts['Cancelled'] || 0) / totalOrders * 100).toFixed(1) 
  : 0;

const returnRate = totalOrders > 0 
  ? ((statusCounts['Returned'] || 0) / totalOrders * 100).toFixed(1) 
  : 0;

// ── FEEDBACK ANALYSIS ────────────────────────────────────

const totalFeedback = recentFeedback.length;

const avgRating = totalFeedback > 0
  ? (recentFeedback.reduce((sum, f) => sum + (parseFloat(f.rating) || 0), 0) / totalFeedback).toFixed(2)
  : 0;

const ratingDistribution = recentFeedback.reduce((acc, f) => {
  const r = String(f.rating);
  acc[r] = (acc[r] || 0) + 1;
  return acc;
}, {});

const negativeFeedback = recentFeedback
  .filter(f => parseFloat(f.rating) <= 2)
  .map(f => `[${f.product_name}] ${f.review_text}`)
  .slice(0, 5); // Top 5 most critical

const positiveFeedback = recentFeedback
  .filter(f => parseFloat(f.rating) >= 4)
  .map(f => `[${f.product_name}] ${f.review_text}`)
  .slice(0, 5);

// Feedback by type
const feedbackTypeCounts = recentFeedback.reduce((acc, f) => {
  acc[f.feedback_type] = (acc[f.feedback_type] || 0) + 1;
  return acc;
}, {});

// ── SUPPORT TICKETS ANALYSIS ─────────────────────────────

const totalTickets = recentTickets.length;
const openTickets = recentTickets.filter(t => t.status === 'Open').length;
const resolvedTickets = recentTickets.filter(t => t.status === 'Resolved').length;
const escalatedTickets = recentTickets.filter(t => t.status === 'Escalated').length;
const highPriorityTickets = recentTickets.filter(t => t.priority === 'High').length;

const issueCategoryCounts = recentTickets.reduce((acc, t) => {
  acc[t.issue_category] = (acc[t.issue_category] || 0) + 1;
  return acc;
}, {});

const topIssueCategory = Object.entries(issueCategoryCounts)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

const resolvedOnly = recentTickets.filter(t => 
  t.status === 'Resolved' && t.resolution_time_hours
);
const avgResolutionTime = resolvedOnly.length > 0
  ? (resolvedOnly.reduce((sum, t) => sum + (parseFloat(t.resolution_time_hours) || 0), 0) / resolvedOnly.length).toFixed(1)
  : 'N/A';

// ── BUILD STRUCTURED SUMMARY FOR GEMINI ──────────────────

const weekStart = sevenDaysAgo.toISOString().split('T')[0];
const weekEnd = now.toISOString().split('T')[0];

const structuredSummary = {
  period: `${weekStart} to ${weekEnd}`,
  orders: {
    total_orders: totalOrders,
    total_revenue_inr: Math.round(totalRevenue),
    avg_order_value_inr: avgOrderValue,
    top_category: topCategory,
    top_city: topCity,
    cancellation_rate_percent: cancelRate,
    return_rate_percent: returnRate,
    status_breakdown: statusCounts,
    payment_method_breakdown: paymentCounts,
    category_revenue_breakdown: categoryRevenue
  },
  customer_feedback: {
    total_reviews: totalFeedback,
    average_rating: avgRating,
    rating_distribution: ratingDistribution,
    feedback_type_breakdown: feedbackTypeCounts,
    sample_negative_reviews: negativeFeedback,
    sample_positive_reviews: positiveFeedback
  },
  support_tickets: {
    total_tickets: totalTickets,
    open_tickets: openTickets,
    resolved_tickets: resolvedTickets,
    escalated_tickets: escalatedTickets,
    high_priority_tickets: highPriorityTickets,
    top_issue_category: topIssueCategory,
    issue_category_breakdown: issueCategoryCounts,
    avg_resolution_time_hours: avgResolutionTime
  }
};

return {
  json: {
    week_start: weekStart,
    week_end: weekEnd,
    total_revenue: Math.round(totalRevenue),
    total_orders: totalOrders,
    avg_order_value: avgOrderValue,
    top_category: topCategory,
    avg_rating: avgRating,
    open_tickets: openTickets,
    top_issue_category: topIssueCategory,
    structured_summary: JSON.stringify(structuredSummary, null, 2)
  }
};

// 1. Fix: Access Gemini output using the correct path from your Input panel
const rawText = $input.item.json.content.parts[0].text;

// Clean markdown
const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse the JSON
let analysis;
try {
  analysis = JSON.parse(cleanedText);
} catch(e) {
  analysis = {
    executive_summary: "Analysis could not be parsed this week.",
    top_trends: []
  };
}

// 2. Fix: Reference the correct node name 'Code in JavaScript' (Node 5 in your workflow)
const metrics = $('Merge and Analyze All Data').item.json;

return {
  json: {
    week_start:           metrics.week_start,
    week_end:             metrics.week_end,
    total_revenue:        metrics.total_revenue,
    total_orders:         metrics.total_orders,
    avg_order_value:      metrics.avg_order_value,
    top_category:         metrics.top_category,
    avg_rating:           metrics.avg_rating,
    open_tickets:         metrics.open_tickets,
    top_issue_category:   metrics.top_issue_category,
    executive_summary:    analysis.executive_summary,
    top_trends:           analysis.top_trends,
    anomalies:            analysis.anomalies || [],
    customer_sentiment:   analysis.customer_sentiment || {},
    support_health:       analysis.support_health || {},
    recommendation_1:     analysis.recommendation_1 || {},
    recommendation_2:     analysis.recommendation_2 || {}
  }
};
